html:
{%- from "templates/print_formats/standard_macros.html" import add_header -%}
{{ add_header(0, 1, doc, letter_head, no_letterhead, footer, print_settings) }}
<style>
.al-doc { font-size: 11px; color: #1f2933; }
.al-doc h2 { font-size: 18px; margin: 0 0 2px; letter-spacing: .02em; }
.al-doc .al-sub { color: #52606d; margin-bottom: 12px; }
.al-doc table { width: 100%; border-collapse: collapse; margin: 8px 0 12px; }
.al-doc th { background: #f0f2f5; text-align: left; font-weight: 600; }
.al-doc th, .al-doc td { border: 1px solid #cbd2d9; padding: 4px 6px; vertical-align: top; }
.al-doc .al-grid td { border: none; padding: 2px 8px 2px 0; }
.al-doc .al-label { color: #52606d; width: 22%; }
.al-doc .num { text-align: right; white-space: nowrap; }
.al-doc .al-worse { font-weight: 700; text-decoration: underline; }
.al-doc .al-sign { margin-top: 36px; }
.al-doc .al-sign td { border: none; border-top: 1px solid #52606d; width: 25%; padding-top: 4px; text-align: center; }
.al-doc .al-note { border-left: 3px solid #9aa5b1; padding: 4px 8px; color: #3e4c59; margin: 8px 0; }
</style>
{%- set company = frappe.db.get_value("Company", doc.company, ["company_name", "tax_id"], as_dict=True) -%}
<div class="al-doc">
<h2>{{ _("Equipment Hire Agreement") }}</h2>
<div class="al-sub">{{ doc.name }} &middot; {{ _(doc.agreement_type) }} &middot; {{ _(doc.hire_type) }}</div>
<table class="al-grid">
<tr><td class="al-label">{{ _("Owner") }}</td><td><b>{{ company.company_name }}</b>{% if company.tax_id %} &middot; {{ company.tax_id }}{% endif %}</td>
<td class="al-label">{{ _("Hirer") }}</td><td><b>{{ doc.customer_name }}</b>{% if doc.customer_address %}<br>{{ frappe.db.get_value("Address", doc.customer_address, "address_line1") or "" }}{% endif %}</td></tr>
<tr><td class="al-label">{{ _("Hire period") }}</td><td>{{ doc.get_formatted("start_date") }} {{ _("to") }} {{ doc.get_formatted("expected_end_date") if doc.expected_end_date else _("open-ended - until returned") }}</td>
<td class="al-label">{{ _("Site") }}</td><td>{{ doc.site_location }}{% if doc.contact_person %}<br>{{ _("Contact") }}: {{ doc.contact_person }}{% endif %}</td></tr>
{% if doc.hire_type == "Wet Hire" %}<tr><td class="al-label">{{ _("Operator") }}</td><td colspan="3">{{ doc.operator }} {{ frappe.db.get_value("Employee", doc.operator, "employee_name") or "" }}</td></tr>{% endif %}
</table>
<table>
<tr><th>#</th><th>{{ _("Equipment") }}</th><th>{{ _("Charge item") }}</th><th class="num">{{ _("Monthly rate") }}</th><th class="num">{{ _("Daily rate") }}</th><th class="num">{{ _("Agreed days") }}</th></tr>
{% for row in doc.items %}
<tr><td>{{ row.idx }}</td><td><b>{{ row.asset }}</b><br>{{ row.asset_name or "" }}</td><td>{{ row.item_name or row.rental_item }}</td>
<td class="num">{{ _("Free of charge") if row.is_free_of_charge else row.get_formatted("monthly_rate", doc) }}</td>
<td class="num">{{ row.get_formatted("derived_daily_rate", doc) if row.derived_daily_rate else "" }}</td>
<td class="num">{{ row.expected_days or "" }}</td></tr>
{% endfor %}
</table>
<table class="al-grid">
{% if doc.estimated_rental_value %}<tr><td class="al-label">{{ _("Estimated rent for the agreed period") }}</td><td>{{ doc.get_formatted("estimated_rental_value") }}</td></tr>{% endif %}
{% if doc.security_deposit_amount %}<tr><td class="al-label">{{ _("Refundable security deposit") }}</td><td>{{ doc.get_formatted("security_deposit_amount") }}</td></tr>{% endif %}
{% if doc.mobilisation_charge %}<tr><td class="al-label">{{ _("Mobilisation") }}</td><td>{{ doc.get_formatted("mobilisation_charge") }}</td></tr>{% endif %}
{% if doc.demobilisation_charge %}<tr><td class="al-label">{{ _("Demobilisation") }}</td><td>{{ doc.get_formatted("demobilisation_charge") }}</td></tr>{% endif %}
</table>
{%- set basis = al_pricing_basis(doc.agreement_type) -%}
{% if basis %}<div class="al-note">{{ basis }}</div>{% endif %}
{% if doc.terms %}<h4>{{ _("Terms and conditions") }}</h4><div>{{ doc.terms }}</div>{% endif %}
<table class="al-sign"><tr><td>{{ _("For") }} {{ company.company_name }}</td><td>{{ _("Approved by") }}</td><td>{{ _("For") }} {{ doc.customer_name }}</td><td>{{ _("Date") }}</td></tr></table>
</div>
